// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

contract StudentRegistry {
    struct Student {
        uint256 rolenum;
        string name;
        string course;
        uint256 year;
        uint256 semester;
        uint256 cgpa;
    }

    mapping(uint256 => Student) private students;
    mapping(uint256 => bool) private studentExists;
    uint256[] private rollNumbers;

    function addStudent(
        uint256 rolenum,
        string calldata name,
        string calldata course,
        uint256 year,
        uint256 semester,
        uint256 cgpa
    ) external {
        require(!studentExists[rolenum], "Roll number already exists.");
        students[rolenum] = Student(rolenum, name, course, year, semester, cgpa);
        studentExists[rolenum] = true;
        rollNumbers.push(rolenum);
    }

    function listAllStudents() external view returns (Student[] memory result) {
        result = new Student[](rollNumbers.length);
        for (uint256 i = 0; i < rollNumbers.length; i++) {
            result[i] = students[rollNumbers[i]];
        }
    }

    function getStudent(uint256 rolenum) external view returns (Student memory) {
        require(studentExists[rolenum], "Student not found.");
        return students[rolenum];
    }

    function modifyCgpa(uint256 rolenum, uint256 newCgpa) external {
        require(studentExists[rolenum], "Student not found.");
        students[rolenum].cgpa = newCgpa;
    }

    function deleteStudent(uint256 rolenum) external {
        require(studentExists[rolenum], "Student not found.");
        delete students[rolenum];
        delete studentExists[rolenum];

        for (uint256 i = 0; i < rollNumbers.length; i++) {
            if (rollNumbers[i] == rolenum) {
                for (uint256 j = i; j < rollNumbers.length - 1; j++) {
                    rollNumbers[j] = rollNumbers[j + 1];
                }
                rollNumbers.pop();
                break;
            }
        }
    }
}
